from pathlib import Path
from datetime import datetime
import requests
import pandas as pd

URL = (
    "https://margincalculator.angelone.in/"
    "OpenAPI_File/files/OpenAPIScripMaster.json"
)

OUT = Path("AngelOne_Instruments")
OUT.mkdir(parents=True, exist_ok=True)


def main():
    print("=" * 65)
    print("ANGEL ONE - NIFTY CURRENT & NEXT EXPIRY OPTIONS")
    print("=" * 65)

    # 1. Remove files generated by previous versions of this script.
    # Only the two CSV output files will be retained.
    keep_files = {
        "nifty_current_expiry.csv",
        "nifty_next_expiry.csv",
    }

    old_files = [
        "all_instruments.json",
        "all_instruments.csv",
        "nifty_index_options.json",
        "nifty_index_options.csv",
        "nifty_current_next_expiry.json",
        "nifty_current_next_expiry.csv",
        "nifty_current_next_expiry.xlsx",
    ]

    for filename in old_files:
        file_path = OUT / filename
        if file_path.is_file() and filename not in keep_files:
            file_path.unlink()

    # Remove previously generated per-expiry CSV files.
    for file_path in OUT.glob("nifty_options_expiry_*.csv"):
        file_path.unlink()

    # 2. Download the instrument master
    print("\nDownloading Angel One instrument master...")

    response = requests.get(
        URL,
        timeout=120,
        headers={"User-Agent": "Mozilla/5.0"},
    )
    response.raise_for_status()

    data = response.json()

    if not isinstance(data, list) or not data:
        raise RuntimeError("Instrument master is empty or invalid.")

    df = pd.DataFrame(data)
    print(f"Total downloaded instruments: {len(df):,}")

    # 3. Normalize column names
    aliases = {
        "token": "symboltoken",
        "symbol": "tradingsymbol",
        "exch_seg": "exchange",
    }

    df.rename(
        columns={
            old: new
            for old, new in aliases.items()
            if old in df.columns and new not in df.columns
        },
        inplace=True,
    )

    # 4. Validate required columns
    required = [
        "name",
        "instrumenttype",
        "exchange",
        "expiry",
    ]

    missing = [col for col in required if col not in df.columns]

    if missing:
        raise RuntimeError(
            f"Missing required columns: {missing}. "
            f"Available columns: {list(df.columns)}"
        )

    # 5. Filter NIFTY index options on NSE F&O
    nifty = df[
        df["name"].fillna("").astype(str).str.strip().str.upper().eq("NIFTY")
        & df["instrumenttype"].fillna("").astype(str).str.strip().str.upper().eq("OPTIDX")
        & df["exchange"].fillna("").astype(str).str.strip().str.upper().eq("NFO")
    ].copy()

    if nifty.empty:
        raise RuntimeError("No NIFTY index options found.")

    print(f"NIFTY index options found: {len(nifty):,}")

    # 6. Parse expiry dates and exclude expired contracts
    nifty["expiry_date"] = pd.to_datetime(
        nifty["expiry"],
        errors="coerce",
        dayfirst=True,
    ).dt.normalize()

    nifty.dropna(subset=["expiry_date"], inplace=True)

    today = pd.Timestamp.now().normalize()

    nifty = nifty[
        nifty["expiry_date"] >= today
    ].copy()

    if nifty.empty:
        raise RuntimeError("No current or upcoming expiries found.")

    # 7. Identify the two nearest distinct expiry dates
    expiries = sorted(nifty["expiry_date"].unique())[:2]

    current_expiry = expiries[0]
    next_expiry = expiries[1] if len(expiries) > 1 else None

    current_df = nifty[
        nifty["expiry_date"] == current_expiry
    ].copy()

    if next_expiry is not None:
        next_df = nifty[
            nifty["expiry_date"] == next_expiry
        ].copy()
    else:
        next_df = nifty.iloc[0:0].copy()

    # 8. Sort contracts and remove the helper column
    def prepare_output(frame):
        frame = frame.copy()

        sort_columns = [
            col for col in ["strike", "tradingsymbol"]
            if col in frame.columns
        ]

        if sort_columns:
            frame.sort_values(sort_columns, inplace=True)

        return frame.drop(columns=["expiry_date"])

    current_df = prepare_output(current_df)
    next_df = prepare_output(next_df)

    # 9. Save ONLY the two CSV files
    current_csv = OUT / "nifty_current_expiry.csv"
    next_csv = OUT / "nifty_next_expiry.csv"

    current_df.to_csv(current_csv, index=False)
    next_df.to_csv(next_csv, index=False)

    # 10. Print summary
    print("\n" + "=" * 65)
    print("DOWNLOAD COMPLETED")
    print("=" * 65)

    print(f"Downloaded at: {datetime.now().isoformat(timespec='seconds')}")
    print(f"Current expiry: {pd.Timestamp(current_expiry).date()}")
    print(f"Current expiry contracts: {len(current_df):,}")

    if next_expiry is not None:
        print(f"Next expiry: {pd.Timestamp(next_expiry).date()}")
        print(f"Next expiry contracts: {len(next_df):,}")
    else:
        print("Next expiry: Not available in the instrument master")

    print("\nSAVED CSV FILES")
    print(f"Current expiry: {current_csv.resolve()}")
    print(f"Next expiry:    {next_csv.resolve()}")

    print("\nOnly the two expiry CSV files are generated.")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"\nDOWNLOAD FAILED: {exc}")
        print("Check your internet connection and instrument master format.")